import { z } from "zod";

export type JudgedFactor = "brand_fit" | "ease";

export interface Judgement {
  value: number;
  note: string;
  by: string;
}

export function cleanJudgementNote(s: string, max = 300): string {
  const t = s.replace(/\s+/g, " ").trim();
  return t.length > max ? `${t.slice(0, max - 1)}…` : t;
}

const JudgedFactorSchema = z.object({
  value: z
    .number()
    .refine(Number.isFinite, { message: "Value must be finite" })
    .transform((v) => Math.max(0, Math.min(5, v))),
  note: z
    .string()
    .min(1)
    .transform((s) => cleanJudgementNote(s)),
});

export const JudgedFactors = z.object({
  brand_fit: JudgedFactorSchema,
  ease: JudgedFactorSchema,
});

export function neutralJudgement(reason: string): Record<JudgedFactor, Judgement> {
  const note = cleanJudgementNote(`Assumption: not judged (${reason}); neutral midpoint.`);
  return {
    brand_fit: {
      value: 2.5,
      note,
      by: "deterministic",
    },
    ease: {
      value: 2.5,
      note,
      by: "deterministic",
    },
  };
}
import {
  describeDrivers,
  FactorScore,
  priorityForScore,
  ScoreBreakdown,
  ScoreFactor,
  scoreFlags,
  weightedTotal,
  type Settings,
} from "@reqflow/core";
import { deterministicFactors, type ScoringEvidence } from "./factors";
import { cleanJudgementNote, type JudgedFactor, type Judgement } from "./judge";

export const PRIORITIZATION_METHOD = "ws8-weighted@1";

export interface ScoreInput {
  evidence: ScoringEvidence;
  judged: Record<JudgedFactor, Judgement>;
  evidenceLevel?: "A" | "B" | "C" | "D";
  scoring: Settings["scoring"];
  now: string; // ISO datetime
}

export function scoreItem(input: ScoreInput): ScoreBreakdown {
  const det = deterministicFactors(input.evidence);
  const factors: Record<string, FactorScore> = {};

  const detKeys: (keyof typeof det)[] = [
    "customer_impact",
    "evidence_strength",
    "competitive_gap",
    "trend_momentum",
  ];
  for (const k of detKeys) {
    const weight = input.scoring.weights[k] ?? 0;
    factors[k] = {
      value: det[k].value,
      weight,
      note: det[k].note,
      by: "deterministic",
    };
  }

  const judgedKeys: JudgedFactor[] = ["brand_fit", "ease"];
  for (const k of judgedKeys) {
    const j = input.judged[k];
    if (!Number.isFinite(j.value)) {
      throw new RangeError(`Judged factor ${k} must be finite, got ${j.value}`);
    }
    const weight = input.scoring.weights[k] ?? 0;
    const value = Math.max(0, Math.min(5, j.value));
    factors[k] = {
      value,
      weight,
      note: cleanJudgementNote(j.note),
      by: j.by,
    };
  }

  const values = Object.fromEntries(
    ScoreFactor.options.map((f) => [f, factors[f]!.value]),
  ) as Record<ScoreFactor, number>;
  const weights = Object.fromEntries(
    ScoreFactor.options.map((f) => [f, factors[f]!.weight]),
  ) as Record<ScoreFactor, number>;

  const total = weightedTotal(values, weights);
  const suggestedPriority = priorityForScore(total, input.scoring.thresholds);
  const flags = scoreFlags(total, input.evidenceLevel, input.scoring.thresholds);

  return ScoreBreakdown.parse({
    factors,
    total,
    suggestedPriority,
    method: PRIORITIZATION_METHOD,
    scoredAt: input.now,
    ...(flags.length ? { flags } : {}),
  });
}

export function explainPriority(
  score: ScoreBreakdown,
  evidenceLevel?: "A" | "B" | "C" | "D",
): string {
  const drivers = describeDrivers(score);
  let text = `Score ${score.total}/100 (${score.suggestedPriority}), driven by ${drivers}.`;
  if (score.flags?.includes("high_score_weak_evidence")) {
    text += ` Its evidence is weak (level ${evidenceLevel ?? "C"}), so check it before approving.`;
  }
  return text;
}
